 t.charge=0;t.lastSlot=-1;t.hitAt=[-99,-99];const delayed=P.Attributes.source(sim.players[1]);sim.use(sim.players[0]);P.state.elapsed+=1;P.Entities.hurt(e,1,0,P.Attributes.source(sim.players[0]));P.state.elapsed+=.5;P.Entities.hurt(e,1,0,delayed);assert.equal(t.charge,5,'Atribuir el proyectil a su dueño, aunque cambie el actor activo');const charge=t.charge;P.Entities.hurt(e,1,0,delayed);assert.equal(t.charge,charge,'No cargar por cada perdigón del mismo disparo');e.hp=0;P.state.elapsed+=1;P.Entities.hurt(e,1,0,P.Attributes.source(sim.players[0]));assert.equal(t.charge,charge,'Un impacto sin daño efectivo no carga');
