test('Evento de dos puestos: tres mapas, posiciones libres, ocupantes distintos y recompensa única',()=>{
 for(const map of ['campo','plaza','machu']){const sim=new Simulation(map,[0,6]),P=sim.P,event=sim.activities.duo,[a,b]=sim.players;assert.equal(event.phase,'locked');assert(!event.start(0));assert(event.positions.every(o=>o&&!P.Terrain.hit(o.x,o.y,55)));assert(distance(event.positions[0],event.positions[1])>=200);P.state.mapTime=45;event.tick(0);assert.equal(event.phase,'ready');assert(!event.start(0),'No activa desde lejos');Object.assign(a,event.positions[0]);Object.assign(b,event.positions[0]);assert(event.start(0));for(let i=0;i<30;i++)event.tick(.1);assert.equal(event.progress,0,'Una misma posición no satisface los dos puestos');Object.assign(b,event.positions[1]);b.hp=0;event.tick(1);assert.equal(event.progress,0,'Un caído no ocupa el puesto');a.hp=a.maxHp/2;b.hp=b.maxHp/2;const coins=P.state.coins;for(let i=0;i<150;i++)event.tick(.1);assert.equal(event.phase,'done');assert.equal(event.progress,15);assert.equal(P.state.coins,coins+35);assert(Math.abs(a.hp-a.maxHp*.7)<.001);assert(Math.abs(b.hp-b.maxHp*.7)<.001);event.tick(10);assert.equal(P.state.coins,coins+35);assert(!event.start(0));assert.doesNotThrow(()=>JSON.stringify(sim.snapshot().duoEvent))}
 function distance(a,b){return Math.hypot(a.x-b.x,a.y-b.y)}
});

