test('Motor compilado reutilizado mantiene independientes las salas',()=>{const a=new Simulation('campo',[0,1]),b=new Simulation('campo',[0,1]);a.P.state.coins=999;a.players[0].hp=1;a.P.state.enemies.push({hp:1});assert.notEqual(b.P.state.coins,999);assert.notEqual(b.players[0].hp,1);assert.equal(b.P.state.enemies.length,0)});

test('Publicación SIGTERM conserva salas hasta quedar libre',{skip:process.platform==='win32',timeout:15000},async()=>{
 const {spawn}=require('node:child_process'),child=spawn(process.execPath,['backend/cooperative.cjs'],{cwd:require('node:path').resolve(__dirname,'..'),env:{...process.env,PORT:'0',ACCOUNTS_DB:'',COOP_ORIGINS:'http://drain.test'},stdio:['ignore','pipe','pipe']});let ws;try{const port=await new Promise((resolve,reject)=>{let output='';child.stdout.on('data',b=>{output+=b;const m=output.match(/Coop ready (\d+)/);if(m)resolve(Number(m[1]))});child.on('error',reject);child.on('exit',()=>reject(Error('Early child exit')))});ws=new WebSocket('ws://127.0.0.1:'+port+'/coop',{origin:'http://drain.test'});const receive=mailbox(ws);await once(ws,'open');ws.send(JSON.stringify({type:'create',protocol:2,character:0,map:'campo'}));await receive('joined');child.kill('SIGTERM');await new Promise(r=>setTimeout(r,150));ws.send(JSON.stringify({type:'ping',sent:7}));assert.equal((await receive('pong')).sent,7);const exited=once(child,'exit');ws.send(JSON.stringify({type:'leave'}));const [code]=await exited;assert.equal(code,0)}finally{ws?.terminate();if(child.exitCode===null)child.kill('SIGKILL')}
});

test('Transporte sin paquetes durante seis segundos inicia recuperación',()=>{const vm=require('node:vm'),fs=require('node:fs'),P={};vm.runInNewContext(fs.readFileSync('src/network/cooperative.js','utf8'),{P,performance:{now:()=>7001}});let closed=false;Object.assign(P.Coop,{active:true,lastPacket:1,lastSend:0,ws:{readyState:1,close(){closed=true}}});P.Coop.tick(.04);assert(closed)});

test('Dominios cooperativos: solicitar sin mutar ni parpadear localmente',()=>{for(const id of ['makanaky','sideral','chamelin']){const probe=new Simulation('campo',[0,1]),index=probe.P.Data.characters.findIndex(c=>c.id===id);if(index<0)continue;const sim=new Simulation('campo',[0,index]),P=sim.P,p=sim.players[1];sim.use(p);if(id==='makanaky')p.ultimate.domainCharge=100;else p.ultimate.charge=100;P.Coop.active=true;P.Coop.session={slot:1};const module=id==='makanaky'?P.Domain:id==='sideral'?P.SideralDomain:P.Chamelin;assert(module.activate(),id);assert.equal(P.Coop.domain,true);assert.equal(id==='makanaky'?p.ultimate.domainCharge:p.ultimate.charge,100);assert(!P.state.domain&&!P.state.sideralDomain&&!P.state.chamelinDomain);P.Coop.paused=true;assert.equal(module.activate(),false);P.Coop.active=false}});
test('Separación libre: terreno de ambos jugadores, sin barrera a 720',()=>{const sim=new Simulation('campo',[0,1]),P=sim.P;P.Systems.spawn=()=>{};P.Combat.tick=()=>{};P.Systems.collect=()=>{};for(const [i,p]of sim.players.entries()){p.x=i?2300:-2300;p.y=900}P.Chunks.sync();for(const p of sim.players){assert([...P.Chunks.cache.values()].some(c=>c.x===Math.floor(p.x/512)&&c.y===Math.floor(p.y/512)));for(let n=0;n<15&&P.Terrain.hit(p.x,p.y,20);n++)p.y+=35}const before=sim.players.map(p=>p.x);sim.tick(.04,[{x:-1,y:0},{x:1,y:0}]);assert(sim.players[0].x<before[0]);assert(sim.players[1].x>before[1]);assert(P.Chunks.cache.size<=162);const c=P.Chunks.cache.get(Math.floor(sim.players[1].x/512)+','+Math.floor(sim.players[1].y/512));assert(c)});
test('Pulsación breve del dominio sobrevive a paquetes de movimiento y se consume una vez',{timeout:10000},async()=>{const app=createCoopServer({autoTick:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port,clients=[];async function connect(){const ws=new WebSocket(origin.replace('http:','ws:')+'/coop',{origin}),receive=mailbox(ws);clients.push(ws);await once(ws,'open');return {ws,receive,send:m=>ws.send(JSON.stringify(m))}}try{const a=await connect(),b=await connect();a.send({type:'create',protocol:2,map:'campo',character:0});const j=await a.receive('joined');const idx=new Simulation('campo',[0]).P.Data.characters.findIndex(c=>c.id==='makanaky');b.send({type:'join',protocol:2,code:j.code,character:idx});await b.receive('joined');a.send({type:'ready',ready:true,revision:2});b.send({type:'ready',ready:true,revision:2});await new Promise(r=>setTimeout(r,20));a.send({type:'start'});await a.receive('state');await b.receive('state');const room=app.rooms.get(j.code),sim=room.sim;sim.P.Systems.spawn=()=>{};sim.players[1].ultimate.domainCharge=100;b.send({type:'input',x:0,y:0,domain:true});b.send({type:'input',x:1,y:0,domain:false});b.send({type:'ping',sent:42});await b.receive('pong');assert(room.members[1].input.domain);app.tick();assert(sim.P.state.domain);assert.equal(sim.P.state.domain.slot,1);assert.equal(sim.players[1].ultimate.domainCharge,0);assert.equal(room.members[1].input.domain,false);const id=sim.P.state.domain.id;app.tick();assert.equal(sim.P.state.domain.id,id);assert(sim.P.state.domain.age>0);for(let i=0;i<365;i++)sim.tick(.04,[{},{}]);assert(!sim.P.state.domain);assert(sim.players.every(p=>p.hp>0));assert.doesNotThrow(()=>JSON.stringify(sim.snapshot()))}finally{clients.forEach(w=>w.terminate());await app.close()}});

test('Caducidad: una sala activa supera 45 min y un resultado inactivo sí se limpia',async()=>{let clock=0,ticks=0;const app=createCoopServer({autoTick:false,now:()=>clock}),ws={readyState:1,bufferedAmount:0,send(){},close(){this.readyState=3}},sim={result:null,tick(){ticks++},snapshot(){return {elapsed:ticks}}};const room={created:0,frame:0,members:[{ws,input:{}}],sim};app.rooms.set('ACTIVE',room);try{clock=46*60000;app.tick();assert.equal(ticks,1);assert(app.rooms.has('ACTIVE'));sim.result='win';app.tick();assert(app.rooms.has('ACTIVE'));clock+=46*60000;app.tick();assert(!app.rooms.has('ACTIVE'))}finally{app.rooms.clear();await app.close()}});
test('Recargar conserva la credencial solo en su pestaña y cuenta, y respeta vencimiento',()=>{const vm=require('node:vm'),fs=require('node:fs'),source=fs.readFileSync('src/network/cooperative.js','utf8'),data=new Map();let now=1000,opened;const storage={setItem:(k,v)=>data.set(k,v),getItem:k=>data.get(k)||null,removeItem:k=>data.delete(k)},P={state:{mode:'menu'},Account:{user:{id:'owner'}},Lobby:{enter(){},show(){}}},scope={P,sessionStorage:storage,Date:{now:()=>now},performance:{now:()=>100}};const load=()=>{vm.runInNewContext(source,scope);P.Coop.open=m=>opened=m};load();P.Coop.session={code:'ABCD1234',token:'1'.repeat(48),slot:1,guest:false};P.Coop.creditedRound='ABCD1234:2';P.Coop.persistSession();load();assert(P.Coop.restoreSaved());assert.equal(opened.type,'resume');assert.equal(opened.slot,1);assert.equal(P.Coop.creditedRound,'ABCD1234:2');assert.equal(P.Coop.reconnecting,true);load();P.Account.user={id:'other'};assert.equal(P.Coop.restoreSaved(),false);assert.equal(data.size,0);P.Account.user={id:'owner'};P.Coop.session={code:'ABCD1234',token:'1'.repeat(48),slot:1,guest:false};P.Coop.persistSession();load();now=50000;assert.equal(P.Coop.restoreSaved(),false);assert.equal(data.size,0)});
test('Combo compartido usa G, no R, y respeta escritura, modificadores y botón móvil',()=>{const vm=require('node:vm'),fs=require('node:fs'),listeners=[],sent=[],P={CoopExtras:{init(){}},Coop:{active:true,send:m=>sent.push(m)}};vm.runInNewContext(fs.readFileSync('src/network/coop-assist.js','utf8'),{P,document:{body:{append(){}},createElement:()=>({setAttribute(){},click(){this.onclick?.()}})},addEventListener:(name,fn)=>listeners.push(fn)});P.CoopAssist.init();P.CoopAssist.combo.hidden=false;P.CoopAssist.combo.disabled=false;const key=(value,extra={})=>listeners.forEach(fn=>fn({key:value,target:{tagName:'CANVAS'},preventDefault(){},...extra}));key('r');assert.equal(sent.length,0);key('g');assert.equal(sent.length,1);key('g',{ctrlKey:true});key('g',{repeat:true});key('g',{target:{tagName:'INPUT'}});assert.equal(sent.length,1);P.CoopAssist.combo.onclick();assert.equal(sent.length,2);assert(sent.every(m=>m.type==='team'))});
test('Desconectar cancela ultis de ambos y descarta pulsaciones mientras falta el compañero',{timeout:10000},async()=>{const app=createCoopServer({autoTick:false});await new Promise(r=>app.server.listen(0,'127.0.0.1',r));const origin='http://127.0.0.1:'+app.server.address().port,clients=[];async function client(){const ws=new WebSocket(origin.replace('http:','ws:')+'/coop',{origin}),receive=mailbox(ws);clients.push(ws);await once(ws,'open');return {ws,receive,send:m=>ws.send(JSON.stringify(m))}}try{const a=await client(),b=await client();a.send({type:'create',protocol:2,map:'campo',character:7});const j=await a.receive('joined');b.send({type:'join',protocol:2,code:j.code,character:0});const bj=await b.receive('joined');a.send({type:'ready',ready:true,revision:2});b.send({type:'ready',ready:true,revision:2});await new Promise(r=>setTimeout(r,20));a.send({type:'start'});await a.receive('state');await b.receive('state');const room=app.rooms.get(j.code);room.sim.P.Systems.spawn=()=>{};room.sim.players[0].ultimate.charge=100;Object.assign(room.sim.players[0].ultimate.combo,{caos:100,aguante:100,hazana:100});room.members[0].input.ultimate=true;const disconnected=once(room.members[1].ws,'close');b.ws.close();await disconnected;assert(!room.members[0].input.ultimate);a.send({type:'input',x:1,y:0,ultimate:true,domain:true});a.send({type:'ping',sent:9});await a.receive('pong');assert(!room.members[0].input.ultimate&&!room.members[0].input.domain);const c=await client();c.send({type:'resume',protocol:2,code:j.code,token:bj.token});await c.receive('joined');app.tick();assert.equal(room.sim.players[0].ultimate.charge,100);assert.equal(room.sim.players[0].ultimate.left,0)}finally{clients.forEach(w=>w.terminate());await app.close()}});

test('Recuperar un resultado ya acreditado no entrega la recompensa dos veces',()=>{const sim=new Simulation('campo',[0,1]),P=sim.P,c=P.Coop;let credited=0;P.CoopMotion=null;P.Meta.result=()=>credited++;P.Game.start=()=>{};P.UI.hud=()=>{};P.Chunks.sync=()=>{};c.showReward=()=>{};c.showResult=()=>{};c.persistSession=()=>{};c.session={code:'ABCD1234',slot:0};c.room={round:1};c.creditedRound='ABCD1234:1';const state=JSON.parse(JSON.stringify(sim.snapshot()));state.result='win';c.receive(state);assert.equal(credited,0);c.resultShown=false;c.room.round=2;c.receive(state);assert.equal(credited,1);assert.equal(c.creditedRound,'ABCD1234:2');c.receive(state);assert.equal(credited,1)});

