test('Red cooperativa: un único estado en vuelo, control y resultado no quedan descartados',()=>{const {createSender}=require('../backend/state-wire.cjs'),diagnostics={droppedStates:0},sender=createSender(diagnostics),messages=[],callbacks=[],ws={readyState:1,bufferedAmount:0,send(data,options,done){messages.push({data,options});callbacks.push(done)}};sender.send(ws,'primer estado',true);for(let i=0;i<100;i++)sender.send(ws,'estado obsoleto',true);assert.equal(messages.length,1);assert.equal(diagnostics.droppedStates,100);sender.send(ws,{type:'pong',sent:1});sender.send(ws,{type:'state',result:'lose'});assert.equal(messages.length,3);assert.equal(messages[1].options.compress,false);callbacks[0]();assert(sender.canState(ws));sender.send(ws,'estado reciente',true);assert.equal(messages.at(-1).data,'estado reciente');callbacks.at(-1)();ws.bufferedAmount=64*1024;assert(!sender.canState(ws));sender.send(ws,'atrasado',true);assert.equal(messages.length,4);sender.send(ws,{type:'pong'});assert.equal(messages.length,5)});

test('Red cooperativa: compactar conserva poses, avisos, estelas, daño y vectores sin mutar combate',()=>{const {encodeState}=require('../backend/state-wire.cjs'),sim=new Simulation('campo',[0,6]),P=sim.P,s=P.state;const e=P.Entities.enemy();e.x=123.123456;e.y=-256.987654;e.rangedAim={x:.123456789,y:.987654321,distance:120};e.tactic={age:.89,next:0,events:[{at:1.25,x:123.123456,y:-256.987654,angle:.123456789,radius:66}]};s.enemies=[e];sim.players[0].shots=[{x:123.123456,y:-256.987654,vx:233.123456,vy:15,history:[{x:120.123456,y:-253.987654}],combatStats:{physicalAttack:999},hits:new Set([e]),damage:7}];s.danger=[{x:100,y:20,combatStats:{physicalAttack:999},hitSlots:[0],radius:60,damage:11}];const packet={type:'state',...sim.snapshot()},before=JSON.stringify(packet),encoded=encodeState(packet),wire=JSON.parse(encoded);assert.equal(JSON.stringify(packet),before);assert.equal(wire.enemies[0].hp,e.hp);assert.equal(wire.enemies[0].rangedAim.x,e.rangedAim.x);assert.equal(wire.enemies[0].tactic.events[0].angle,e.tactic.events[0].angle);assert(Math.abs(wire.enemies[0].x-e.x)<.005);assert.equal(wire.shots[0].history.length,1);assert.equal(wire.shots[0].damage,7);assert.equal(wire.shots[0].combatStats,undefined);assert.equal(wire.danger[0].hitSlots,undefined);assert.equal(wire.danger[0].radius,60);assert(sim.players[0].shots[0].combatStats);assert(encoded.length<before.length)});
